title:
// main.js (ESM)
import { message } from './counter.js';
export const mainMessage = 'Hello';

// counter.js (ESM)
import { mainMessage } from './main.js';
setTimeout(() => {
    console.log(mainMessage); // 'Hello' — 나중에 채워진 값이 반영됨
}, 0);
// setTimeout이 필요한 이유:
// 평가가 끝나기 전에 접근하면 아직 빈 상태라서
// 평가가 완료된 후에 접근해야 값이 있음

